css:
.print-format { page-width: 100mm; page-height: 75mm; margin-top: 3mm; margin-bottom: 3mm; margin-left: 3mm; margin-right: 3mm;
	padding: 0; font-size: 11px; }
.tm-tag { display: flex; gap: 8px; }
.tm-tag table { width: 100%; border-collapse: collapse; }
.tm-tag td { padding: 1px 3px; vertical-align: top; }
.tm-tag td.k { color: #555; width: 38%; }
.tm-tag .big { font-size: 18px; font-weight: 700; }
.tm-tag .grade { font-size: 26px; font-weight: 800; border: 2px solid #000; padding: 0 8px; display: inline-block; }
.tm-qr { text-align: center; }
.tm-qr svg { width: 30mm; height: 30mm; }
